?>
<div class="d-flex flex-column flex-lg-row justify-content-between align-items-lg-center gap-3 mb-4"><div><h1 class="h2 mb-1">Symbolbibliothek</h1><p class="text-body-secondary mb-0">Durchsuchen, filtern und verwalten Sie alle verfügbaren Verkehrszeichen und Symbole.</p></div><a href="/symbols/create" class="btn btn-primary"><i class="bi bi-upload me-2"></i>Symbol hochladen</a></div>
<div class="row g-4"><div class="col-lg-3"><div class="card shadow-sm sticky-lg-top"><div class="card-header"><h2 class="h5 mb-0">Kategorien</h2></div><div class="list-group list-group-flush"><a href="/symbols" class="list-group-item list-group-item-action <?= $currentCategory === '' ? 'active' : '' ?>">Alle Kategorien</a><?php foreach ($categories as $category): ?><?php $value = (string) (is_array($category) ? ($category['name'] ?? $category['category'] ?? '') : (string) $category); ?><a href="/symbols?category=<?= View::e($value) ?>" class="list-group-item list-group-item-action <?= $currentCategory === $value ? 'active' : '' ?>"><?= View::e($value) ?></a><?php endforeach; ?></div></div></div><div class="col-lg-9"><div class="card shadow-sm mb-4"><div class="card-body"><form method="get" action="/symbols" class="row g-3 align-items-end"><?= CSRF::field() ?><div class="col-md-8"><label for="symbol-search" class="form-label">Suche</label><input type="search" class="form-control" id="symbol-search" name="search" value="<?= View::e($currentSearch) ?>" placeholder="Name, Zeichennummer oder Tags"></div><div class="col-md-4"><label for="category-filter" class="form-label">Kategorie</label><select class="form-select" id="category-filter" name="category"><option value="">Alle Kategorien</option><?php foreach ($categories as $category): ?><?php $value = (string) (is_array($category) ? ($category['name'] ?? $category['category'] ?? '') : (string) $category); ?><option value="<?= View::e($value) ?>" <?= $currentCategory === $value ? 'selected' : '' ?>><?= View::e($value) ?></option><?php endforeach; ?></select></div><div class="col-12 d-flex justify-content-end"><button type="submit" class="btn btn-outline-primary">Filtern</button></div></form></div></div><div class="row g-3"><?php if ($symbols === []): ?><div class="col-12"><div class="alert alert-light border text-body-secondary mb-0">Keine Symbole gefunden.</div></div><?php endif; ?><?php foreach ($symbols as $symbol): ?><div class="col-12 col-sm-6 col-xl-4"><div class="card h-100 shadow-sm"><div class="ratio ratio-4x3 bg-body-tertiary"><img src="<?= View::e((string) rsa21_data_get($symbol, 'file_path', '')) ?>" class="object-fit-contain p-3" alt="<?= View::e((string) rsa21_data_get($symbol, 'name', 'Symbol')) ?>"></div><div class="card-body d-flex flex-column gap-2"><div class="d-flex justify-content-between align-items-start gap-2"><div><h3 class="h6 mb-1"><?= View::e((string) rsa21_data_get($symbol, 'name', 'Symbol')) ?></h3><div class="small text-body-secondary"><?= View::e((string) rsa21_data_get($symbol, 'category', '')) ?> · <?= View::e((string) rsa21_data_get($symbol, 'sign_number', '')) ?></div></div><form method="post" action="/symbols/<?= View::e((string) rsa21_data_get($symbol, 'id', '')) ?>/favourite"><?= CSRF::field() ?><button class="btn btn-sm btn-outline-warning" type="submit" aria-label="Favorit umschalten"><i class="bi <?= rsa21_bool(rsa21_data_get($symbol, 'is_favourite', false)) ? 'bi-star-fill' : 'bi-star' ?>"></i></button></form></div><p class="text-body-secondary small mb-0"><?= View::e((string) rsa21_data_get($symbol, 'description', '')) ?></p><div class="mt-auto d-flex justify-content-between align-items-center"><span class="badge text-bg-light"><?= View::e((string) rsa21_data_get($symbol, 'file_type', 'svg')) ?></span><a href="/symbols/<?= View::e((string) rsa21_data_get($symbol, 'id', '')) ?>/edit" class="btn btn-sm btn-outline-secondary">Bearbeiten</a></div></div></div></div><?php endforeach; ?></div></div></div>
